#include "llama.h"
#include <fstream>
#include <iterator>
#include <iostream>
#include <vector>
#include <limits>
#include <mach-o/dyld.h>
int main(int argc,char **argv) {
    if(argc<3) {std::cerr<<"model and explicit text files required\n";return 2;}
    for(uint32_t i=0;i<_dyld_image_count();i++) std::cerr<<"AUDIT_IMAGE="<<_dyld_get_image_name(i)<<"\n";
    ggml_backend_dev_t devices[]={nullptr};
    auto p=llama_model_default_params();
    p.devices=devices; p.split_mode=LLAMA_SPLIT_MODE_NONE;
    p.n_gpu_layers=0; p.vocab_only=true; p.check_tensors=false;
    auto *m=llama_model_load_from_file(argv[1],p);
    if(!m) return 3;
    auto *v=llama_model_get_vocab(m);
    for(int i=2;i<argc;i++) {
        std::ifstream f(argv[i],std::ios::binary);
        if(!f) {llama_model_free(m);return 4;}
        std::string s((std::istreambuf_iterator<char>(f)),{});
        if(s.size()>1048576) {llama_model_free(m);return 5;}
        std::vector<llama_token> ids(s.size()+256);
        int n=llama_tokenize(v,s.data(),int32_t(s.size()),ids.data(),int32_t(ids.size()),false,true);
        if(n<0) {llama_model_free(m);return 6;}
        std::cout<<"[";
        for(int j=0;j<n;j++) {if(j)std::cout<<",";std::cout<<ids[j];}
        std::cout<<"]\n";
    }
    llama_model_free(m);return 0;
}
